CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE OR REPLACE FUNCTION fn_normalize_vn_phone(raw_phone TEXT)
RETURNS TEXT LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
  digits TEXT;
  prefix_map JSONB := '{
    "0162":"032","0163":"033","0164":"034","0165":"035",
    "0166":"036","0167":"037","0168":"038","0169":"039",
    "0120":"070","0121":"079","0122":"077","0126":"076","0128":"078",
    "0123":"083","0124":"084","0125":"085","0127":"081","0129":"082",
    "0186":"056","0188":"058","0199":"059"
  }'::JSONB;
  p4 TEXT;
BEGIN
  IF raw_phone IS NULL THEN RETURN NULL; END IF;
  digits := regexp_replace(raw_phone, '[^0-9]', '', 'g');
  IF digits ~ '^0084' THEN digits := '0' || substring(digits FROM 5);
  ELSIF digits ~ '^84' AND length(digits) IN (11, 12) THEN digits := '0' || substring(digits FROM 3);
  ELSIF length(digits) = 9 AND digits ~ '^[35789]' THEN digits := '0' || digits;
  END IF;
  IF length(digits) = 11 THEN
    p4 := substring(digits FROM 1 FOR 4);
    IF prefix_map ? p4 THEN digits := (prefix_map ->> p4) || substring(digits FROM 5); END IF;
  END IF;
  IF digits ~ '^0[35789][0-9]{8}$' THEN RETURN '+84' || substring(digits FROM 2); END IF;
  RETURN NULL;
END;
$$;

