import re, unicodedata
from dataclasses import dataclass
from rapidfuzz import fuzz

STOPWORDS = {"cong ty", "tnhh", "co phan", "cp", "tm", "dv", "thuong mai", "dich vu"}

def normalize_vn_company(name: str) -> str:
    s = unicodedata.normalize("NFC", name or "").strip().lower().replace("đ", "d")
    s = "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn")
    s = re.sub(r"[^a-z0-9\s]", " ", s)
    for sw in sorted(STOPWORDS, key=len, reverse=True):
        s = re.sub(rf"\b{re.escape(sw)}\b", " ", s)
    return re.sub(r"\s+", " ", s).strip()

@dataclass
class CandidateScore:
    golden_id: str; score: float; decision: str; reasons: list[str]

def score_entity_pair(incoming: dict, existing: dict) -> CandidateScore:
    score, reasons = 0.0, []
    if incoming.get("mst_full") and incoming["mst_full"] == existing.get("mst_full"):
        score += 0.92; reasons.append("EXACT_MST_FULL")
    if incoming.get("phone_e164") and incoming["phone_e164"] == existing.get("phone_e164"):
        score += 0.35 if existing.get("is_shared_line") else 0.78
        reasons.append("SHARED_PHONE" if existing.get("is_shared_line") else "EXACT_PHONE")
    n1, n2 = normalize_vn_company(incoming.get("name", "")), normalize_vn_company(existing.get("name", ""))
    if n1 and n2:
        sim = fuzz.token_set_ratio(n1, n2) / 100.0
        if sim >= 0.88:
            score += 0.25 * sim; reasons.append(f"FUZZY_NAME_{sim:.2f}")
    if incoming.get("email_norm") and incoming["email_norm"] == existing.get("email_norm"):
        score += 0.45; reasons.append("EXACT_EMAIL")
    final_score = min(1.0, round(score, 3))
    decision = "AUTO_MERGE" if final_score >= 0.90 else ("QUARANTINE_REVIEW" if final_score >= 0.68 else "CREATE_NEW")
    return CandidateScore(existing["golden_id"], final_score, decision, reasons)

def explode_marketing_sku(seller_sku: str, qty: int, bom_map: dict[str, list[dict]]) -> list[dict]:
    components = bom_map.get(seller_sku)
    if not components:
        return [{"misa_code": seller_sku, "qty": qty, "revenue_ratio": 1.0, "unmapped": True}]
    return [{"misa_code": c["misa_code"], "qty": qty * c["units"], "revenue_ratio": c["ratio"], "unmapped": False} for c in components]
